function wfTrend(c,values=c.series,post=false){const all=[...c.series,...c.after,c.threshold],lo=Math.min(...all)*.85,hi=Math.max(...all)*1.1,y=v=>160-(v-lo)/(hi-lo)*125;return `<svg class="journey-chart" viewBox="0 0 540 200" role="img" aria-label="${c.metric}${post?'复测':'原始'}趋势">${[0,1,2,3].map(i=>`<line x1="40" x2="510" y1="${35+i*42}" y2="${35+i*42}" stroke="#e7edf5"/>`).join('')}<line x1="40" x2="510" y1="${y(c.threshold)}" y2="${y(c.threshold)}" stroke="#dc9860" stroke-dasharray="5 5"/><text x="45" y="${y(c.threshold)-7}">演示警戒线 ${c.threshold}${c.unit}</text><polyline points="${values.map((v,i)=>`${55+i*88},${y(v)}`).join(' ')}" fill="none" stroke="${post?'#159883':'#4c73db'}" stroke-width="3"/>${values.map((v,i)=>`<circle cx="${55+i*88}" cy="${y(v)}" r="4" fill="${post?'#159883':'#4c73db'}"/><text x="${45+i*88}" y="${y(v)-10}">${v}</text><text x="${45+i*88}" y="190">T${i+1}</text>`).join('')}</svg><p>${c.window} · ${c.metric} / ${c.unit} · 固定合成样本</p>`}
function wfHistory(r){return `<ul class="timeline">${r.history.map(h=>`<li><b>${esc(h.action)}</b><small>${h.time}</small><p>${esc(h.detail)}</p><span class="subtext">${h.id}</span></li>`).join('')||'<li>尚未操作。请从证据核验开始。</li>'}</ul>`}

