const nativeAck=ackAlarm,nativeCreate=createWork,nativeEscalate=escalateAlarm,nativeSuppress=suppressAlarm;
ackAlarm=id=>{if(!allowed('operator'))return denied();const key=caseForAlarm(id);if(key)return wfAck(key,$('#alarm-reason')?.value||$('#wf-note')?.value);const result=nativeAck(id),a=state.alarms.find(a=>a.id===id);if(a?.status==='已确认'){a.acknowledgedBy=state.demoPerson;a.acknowledgedAt=time();save()}return result};
createWork=id=>{if(!allowed('operator','supervisor'))return denied();const key=caseForAlarm(id);if(key){openCase(key,'actions');return toast('此事件先由诊断人员提交方案，主管审批后自动分派工单')}const n=state.work.length;nativeCreate(id);if(state.work.length>n){state.work.at(-1).history[0].actor=person().name;save()}return state.work.length>n};
escalateAlarm=id=>allowed('operator','supervisor')?nativeEscalate(id):denied();
suppressAlarm=id=>allowed('supervisor')?nativeSuppress(id):denied();
transitionWork=(id,action,version)=>{
 const w=state.work.find(w=>w.id===id);if(!w||w.journey)return denied();if(w.version!==version)return toast('版本已变化，请重新打开工单');
 const supervisor=allowed('supervisor'),mine=allowed('engineer')&&w.ownerId===state.demoPerson;
 if(!supervisor&&!mine)return denied();let note=reason('#work-reason');if(!note)return false;let next;
 if(action==='reopen'){if(!supervisor||!['已关闭','已取消'].includes(w.status))return denied();next='待分派';w.ownerId=null;w.owner='';w.testPassed=false}
 else if(action==='cancel'){if(!supervisor||['已关闭','已取消'].includes(w.status))return denied();next='已取消'}
 else if(action==='reject'){if(!supervisor||!['待审批','待审核'].includes(w.status))return denied();next='排查中';w.testPassed=false}
 else if(action==='next'){
  if(w.status==='待分派'){const owner=$('#work-owner')?.value;if(!supervisor||PEOPLE[owner]?.kind!=='engineer')return denied();w.ownerId=owner;w.owner=PEOPLE[owner].name;next='待接单'}
  else if(w.status==='待接单'&&mine)next='排查中';
  else if(w.status==='排查中'&&mine)next='待审批';
  else if(w.status==='待审批'&&supervisor)next='处置中';
  else if(w.status==='处置中'&&mine)next='待复测';
  else if(w.status==='待复测'&&mine){const test=$('#work-test')?.value;if(!['通过','不通过'].includes(test))return toast('请填写复测结论');w.testPassed=test==='通过';w.testActor=state.demoPerson;state.alarms.find(a=>a.id===w.alarm).signalState=w.testPassed?'recovered':'active';note+='；复测：'+test;w.tests=w.tests||[];w.tests.push({id:`TEST-${w.id}-${w.tests.length+1}`,passed:w.testPassed,actor:state.demoPerson,time:time(),note});next=w.testPassed?'待审核':'排查中'}
  else if(w.status==='待审核'&&supervisor&&w.testPassed&&w.testActor!==state.demoPerson&&w.ownerId!==state.demoPerson)next='已关闭';
  else return denied();
 }else return false;
 const old=w.status;w.status=next;w.version++;w.history.push({time:time(),from:old,to:next,reason:note,actor:person().name});const a=state.alarms.find(a=>a.id===w.alarm);a.status=next==='已关闭'?'已关闭':next==='已取消'?'已确认':'处理中';log('工单状态变更',id,`${old} → ${next} / ${note}`);render();return true;
};
