function decisionStage(id){const s=jr(id).stage;return ['discovered','acknowledged'].includes(s)?0:['requested','rejected'].includes(s)?1:['analyzed','deferred','assigned','executing'].includes(s)?2:3}
function decisionGap(id){const r=jr(id);if(r.quality!=='有效')return `输入${r.quality}：林管理员修复质量后，由诊断人员重新核验；禁止据此批准或复测。`;return ({discovered:'待值班核对证据并接管；尚无有效诊断。',acknowledged:'待值班提交诊断请求；确认告警不等于恢复。',requested:'待分析人员核对来源、竞争假设与缺失证据。',rejected:'主管已退回：补充证据并重新提交诊断。',analyzed:'待主管比较方案、填写依据并指定执行人。',deferred:'方案已暂缓；主管需补齐决策依据后再审批。',assigned:'已批准；仅被分派工程师可接单。',executing:`待完成 ${cs(id).checks.filter((_,i)=>!r.checks[i]).length} 项检查并提交记录。`,retest:'待被分派工程师提交有效复测证据。',review:'复测已通过，仍待主管独立验收。',closed:'已验收并回写本地案例；经验须复核后才能推广。'})[r.stage]}
function decisionRail(id){const r=jr(id),active=decisionStage(id),labels=['发现与证据','AI 辅助分析','人工决策与执行','复测与回写'],tabs=['evidence','analysis','actions','evidence'];return `<section class="decision-path" aria-label="事件四阶段路径"><div class="decision-steps">${labels.map((label,i)=>`<button class="decision-step ${i===active?'current':i<active?'complete':''}" ${i===active?'aria-current="step"':''} onclick="detailTab('${tabs[i]}')"><small>0${i+1} · ${r.stage==='closed'?'已完成':i===active?'当前阶段':i<active?'已有记录':'待推进'}</small><b>${label}</b></button>`).join('')}</div><div class="decision-next"><div><b>${r.quality!=='有效'?'林管理员 · 先修复证据质量':nextOwner(id)}</b>${r.quality!=='有效'?`<p>业务责任仍为：${nextOwner(id)}</p>`:''}<p>${decisionGap(id)}</p></div>${wfAction(r.quality!=='有效'?'查看质量阻断':r.stage==='closed'?'查看案例回写':'查看当前交接',`detailTab('${r.quality!=='有效'?'evidence':r.stage==='closed'?'analysis':'actions'}')`)}</div></section>`}
function evidenceSummary(id){const c=cs(id),r=jr(id),ctx=DECISION_CONTEXT[id];return `<section class="support-block"><span class="eyebrow">EVIDENCE READINESS</span><h3>证据质量与对照 ${badge(r.quality)}</h3><p>${c.window} · 原始快照 ${c.evidence}</p><div class="evidence-metrics"><div><small>窗口内变化</small><b>${c.series[0]} → ${c.series.at(-1)} ${c.unit}</b></div><div><small>完整性</small><b>${r.quality==='缺失'?'输入缺失':'6 / 6 合成样本'}</b></div><div><small>时效状态</small><b>${r.quality==='迟到'?'迟到，不可审批':'历史快照，非实时'}</b></div></div><p><b>趋势 / 对照：</b>${ctx.comparison}</p><p><b>待补证据：</b>${ctx.gap}</p><p class="subtext">样本完整不等于现场证据充分；6 个固定样本不构成预测模型验证集。</p></section>`}
function knowledgeMapping(id){const c=cs(id),r=jr(id),d=r.diagnoses.at(-1),valid=d&&!d.blocked&&!d.superseded&&r.quality==='有效';return `<section class="support-block"><span class="eyebrow">KNOWLEDGE → EVIDENCE → HYPOTHESIS</span><h3>知识如何参与本次研判</h3><p>${valid?'已提交的规则研判链':'待核验研判链预览，尚不构成获批诊断'} · ${c.kb} · ${WF_KNOWLEDGE[c.kb].version}</p>${c.hypotheses.map((h,i)=>`<div class="reasoning-link"><b>${i+1}. ${h[0]}</b><p>事件事实：${h[2]}</p><p>知识关联：${i===0?WF_KNOWLEDGE[c.kb].passage:WF_KNOWLEDGE[c.kb].boundary}</p><span class="badge info">${h[1]}</span><p class="subtext">事实来源 ${c.evidence}；知识仅提供核验方向，不能证明根因。下方可核对原始来源、版本与适用范围。</p></div>`).join('')}<h3>条件风险与干预时机</h3><p><b>影响：</b>${c.impact} · <b>观察窗口：</b>${c.horizon}</p><p>${r.stage==='closed'?'已验收结论：'+c.outcome:r.quality!=='有效'?'质量门禁阻断，当前不输出有效风险推演。':d&&(d.blocked||d.superseded)?'上次诊断已阻断或失效，须重新核验并提交；当前不输出有效风险推演。':(valid?'已提交的条件风险研判：':'待核验条件推演示例（尚无有效诊断）：')+c.forecast}</p><p><b>成立前提：</b>${DECISION_CONTEXT[id].assumption}</p><p><b>不确定性 / 下一步：</b>${DECISION_CONTEXT[id].gap}</p><div class="split-note">条件推演用于确定检查优先级。无真实模型推理、无故障概率、无准确率或寿命承诺。${r.stage==='closed'?'此处保留处置前研判，不代表当前风险。':''}</div></section>`}
function planComparison(id){const c=cs(id);return `<section class="support-block"><span class="eyebrow">HUMAN DECISION</span><h3>处置方案比较</h3><p>以下为演示决策草案；资源、时间窗与回退条件须现场负责人确认，选择方案后仍需主管批准。</p>${c.plans.map((p,i)=>{const x=DECISION_CONTEXT[id].plans[i];return `<article class="plan-option"><h4>方案 ${i+1} · ${p}</h4><dl><dt>预期影响 / 代价</dt><dd>${x[0]}</dd><dt>人员与资源</dt><dd>${x[1]}</dd><dt>执行窗口</dt><dd>${x[2]}</dd><dt>停止 / 回退条件</dt><dd>${x[3]}</dd></dl></article>`}).join('')}</section>`}
function retestComparison(id){const c=cs(id),r=jr(id),t=r.tests.at(-1);return `<section class="support-block"><span class="eyebrow">VERIFY & LEARN</span><h3>处置前后对照与回写</h3>${table(['比较项','处置前','最新复测'],[`<tr><td>${c.metric}</td><td>${c.series.at(-1)} ${c.unit}</td><td>${t?t.values.at(-1)+' '+c.unit:'尚未复测'}</td></tr>`,`<tr><td>证据编号</td><td>${c.evidence}</td><td>${t?t.evidence:'待生成'}</td></tr>`,`<tr><td>业务结论</td><td>异常待核验</td><td>${t?(t.passed?'测量通过，'+(r.stage==='closed'?'已独立验收':'仍需独立验收'):'复测失败，已返回排查'):'不能声称恢复'}</td></tr>`])}<p>比较口径：${c.window}，使用固定合成回放；真实验收还需确认负载、环境与测量方法可比。</p><p>${r.tests.filter(x=>!x.passed).length} 次失败记录保留；失败会清空检查项并返回工程师排查，主管可将通过复测退回返工。</p>${r.caseId?`<div class="split-note"><b>${r.caseId} · 已回写本地案例</b><p>链路：${c.evidence} → ${r.diagnoses.at(-1)?.id} → ${r.decisions.at(-1)?.id} → ${r.workId} → ${t?.id}</p><p>复盘结论：${c.outcome}</p><p>验收依据：${esc(r.reviewNote)}</p><p>知识复用：保留来源和适用范围，人工审核后再用于相似事件；未训练模型、未自动发布规程。</p></div>`:'<p>主管独立验收后才生成案例编号，自动关联证据、诊断、决策、工单与复测记录。</p>'}</section>`}
const baseCaseDetail=caseDetail;
caseDetail=(id,tab)=>{const body=baseCaseDetail(id,tab);if(tab==='overview')return `<div class="split-note"><b>本次 AI 辅助价值</b><p>${cs(id).subtitle}</p><p>把监测事实与可核验知识关联，输出有前提的风险研判，由人选择方案并用复测验证。</p>${wfAction('查看知识与研判链',"detailTab('analysis')")}</div>`+body;if(tab==='evidence')return evidenceSummary(id)+retestComparison(id)+body;if(tab==='analysis')return knowledgeMapping(id)+body;return body};
const baseCaseActions=caseActions;
caseActions=id=>planComparison(id)+baseCaseActions(id);
const baseDrawDetail=drawDetail;
drawDetail=()=>{baseDrawDetail();if(detail?.caseId&&detailDialog.open)detailDialog.querySelector('.drawer-tabs')?.insertAdjacentHTML('beforebegin',decisionRail(detail.caseId))};
detailTabs[2][1]='AI 研判与知识依据';detailTabs[3][1]='人工决策与执行';
const baseQueueTable=queueTable;
queueTable=ids=>table(['事件 / AI 辅助线索','状态 / 缺项','当前责任人','操作'],ids.map(id=>`<tr><td class="wrap-cell"><strong>${cs(id).title}</strong><span class="id">${cs(id).event} · ${cs(id).kb}</span><span class="subtext">${cs(id).subtitle}</span></td><td class="wrap-cell">${badge(stageLabel[jr(id).stage])}<span class="id">${decisionGap(id)}</span></td><td>${nextOwner(id)}</td><td>${wfAction('查看研判链',`openCase('${id}','analysis')`)} ${wfAction('处理待办',`openCase('${id}','actions')`)}</td></tr>`));
const baseAlarmRows=alarmRows;
alarmRows=alarms=>alarms.map(a=>{const id=caseForAlarm(a.id),row=baseAlarmRows([a])[0];return id?row.replace(`<span class="id">${a.id}</span>`,`<span class="id">${a.id}</span><button class="ai-clue" onclick="openCase('${id}','analysis')">AI 辅助 · ${cs(id).kb} · ${jr(id).quality==='有效'?'可查研判依据':'质量阻断'}</button>`):row});
function decisionHighlights(){const ids=visibleCases();return `<section class="card decision-highlights">${head('AI 辅助研判 · 从证据到行动',badge('固定规则演示'))}<p>知识有来源，风险有前提，处置由人审批，效果由复测验证。</p><div class="highlight-grid">${ids.map(id=>`<button onclick="openCase('${id}','analysis')"><small>${cs(id).tag} · ${stageLabel[jr(id).stage]}</small><b>${cs(id).title}</b><span>${cs(id).kb} · ${cs(id).horizon}</span></button>`).join('')}</div></section>`}
const baseOverview=views.overview;
views.overview=()=>decisionHighlights()+baseOverview();

// v4: one work-order aggregate owns lifecycle, evidence and role handoffs.
const WO_PHASE_STATUS={acknowledged:'待分析',requested:'待分析',rejected:'待分析',analyzed:'待方案审批',deferred:'待方案审批',dispatch:'待派单',assigned:'待接单',executing:'处理中',retest:'待复测',review:'待验收',closed:'已关闭',cancelled:'已取消'};
const WO_STATUS_PHASE={'待分析':'requested','待方案审批':'analyzed','待派单':'dispatch','待接单':'assigned','处理中':'executing','待复测':'retest','待验收':'review','已关闭':'closed','已取消':'cancelled','待分派':'dispatch','已分派':'assigned','已接单':'executing','排查中':'executing','处置中':'executing','待审批':'analyzed','待审核':'review'};
const WO_TYPES=['故障处理','预测性维护','预防性巡检','容量变更'];
const WO_PRIORITIES=['紧急','高','中','低'];
function bindWork(w,r=w.flow){
 const oldStatus=w.status,legacy=!w.phase;
 w.phase=w.phase||r?.stage||WO_STATUS_PHASE[oldStatus]||'requested';
 if(!WO_PHASE_STATUS[w.phase])w.phase='requested';
 w.history=Array.isArray(w.history)?w.history:[];w.version=Number(w.version)||1;
 w.source=w.source||(w.journey?'预测预警':w.alarm?'告警接管':'人工创建');w.type=w.type||'故障处理';w.priority=w.priority||'中';w.description=w.description||w.title;w.site=dev(w.device)?.site||w.site;
 w.evidence=Array.isArray(w.evidence)?w.evidence:[];w.diagnoses=Array.isArray(w.diagnoses)?w.diagnoses:[];w.decisions=Array.isArray(w.decisions)?w.decisions:[];w.tests=Array.isArray(w.tests)?w.tests:[];
 Object.defineProperty(w,'status',{enumerable:true,configurable:true,get(){return WO_PHASE_STATUS[this.phase]},set(v){const next=WO_STATUS_PHASE[v];if(next&&WO_PHASE_STATUS[this.phase]!==WO_PHASE_STATUS[next])this.phase=next}});
 if(r){w.flow=r;r.workId=w.id;Object.defineProperty(r,'stage',{enumerable:true,configurable:true,get(){return w.phase},set(v){if(WO_PHASE_STATUS[v])w.phase=v}});w.evidenceId=w.evidenceId||CASES[w.journey]?.evidence;w.knowledgeId=w.knowledgeId||CASES[w.journey]?.kb;
  if(!w.evidence.length)w.evidence.push({id:w.evidenceId,workId:w.id,kind:'事件原始快照',values:[...CASES[w.journey].series],window:CASES[w.journey].window});
  for(const k of ['diagnoses','decisions','tests']){w[k]=r[k];for(const x of r[k])x.workId=w.id}for(const h of r.history)h.workId=w.id;
 }
 for(const h of w.history)h.workId=w.id;
 if(legacy&&!r&&(!PEOPLE[w.ownerId]&&['assigned','executing','retest','review'].includes(w.phase)||w.phase==='analyzed'&&!w.diagnoses.length)){
  w.phase='requested';w.ownerId=null;w.owner='';w.history.push({workId:w.id,time:time(),from:oldStatus,to:w.status,actor:'版本迁移',reason:'迁移待核验：旧记录缺少固定执行人或可核验分析，保留历史并补充分析后重新审批'});
 }
 return w;
}
function migrationAudit(w){state.audits.unshift({id:`AUDIT-MIGRATE-${w.id}`,time:time(),actor:'系统 · 版本迁移',action:'迁移补建',target:w.id,detail:'旧版记录补建工单并保留证据；非历史人工操作'});}
function makeWork(data,r){
 const existing=state.work.find(w=>data.eventId&&w.eventId===data.eventId||data.alarm&&w.alarm===data.alarm||data.id&&w.id===data.id);if(existing)return existing;
 const id=data.id||`WO-${Date.now()}-${(state.workSequence=(state.workSequence||0)+1).toString().padStart(3,'0')}`;
 const w={...data,id,phase:r?.stage&&r.stage!=='discovered'?r.stage:'requested',ownerId:null,owner:'',version:1,history:[],createdAt:time()};state.work.push(w);bindWork(w,r);return w;
}
function ensureCaseWork(id){const c=CASES[id],r=state.journeys.records[id];const w=makeWork({id:r.workId||`WO-FLOW-${id.toUpperCase()}`,journey:id,eventId:c.event,alarm:c.alarm,device:c.device,title:c.title,source:'预测预警',type:id==='capacity'?'容量变更':'预测性维护',priority:'高',description:c.subtitle},r);r.workId=w.id;const a=state.alarms.find(a=>a.id===c.alarm);a.work=w.id;return w}
function workAudit(w,action,note,from=w.status){
 w.version++;const h={id:`TRACE-${w.id}-${w.history.length+1}`,workId:w.id,time:time(),actor:state.demoPerson,actorName:person().name,from,to:w.status,action,reason:note};w.history.push(h);log(action,w.id,note);save();return h;
}
wfLog=(id,action,note)=>{wfSync();const r=jr(id),w=state.work.find(w=>w.id===r.workId);r.history.push({id:`TRACE-${id}-${r.history.length+1}`,workId:r.workId,time:time(),actor:state.demoPerson,action:person().name+' · '+action,detail:note});if(w){for(const h of w.history)h.workId=w.id;for(const k of ['diagnoses','decisions','tests']){w[k]=r[k];for(const x of r[k])x.workId=w.id}workAudit(w,action,note,w.history.at(-1)?.to||'新建')}else log(action,cs(id).event,note);save()};
function wfDispatch(id,assignee,note){if(!CASES[id]||!allowed('supervisor')||jr(id).stage!=='dispatch'||jr(id).quality!=='有效'||PEOPLE[assignee]?.kind!=='engineer'||!String(note||'').trim())return false;const r=jr(id),w=state.work.find(w=>w.id===r.workId);w.ownerId=assignee;w.owner=PEOPLE[assignee].name;r.stage='assigned';return wfCommit(id,'分派工单',`${w.id} / ${w.owner} / ${note}`)}
function workResponsible(w){if(['acknowledged','requested','rejected'].includes(w.phase))return '周分析 · 分析';if(['analyzed','deferred','dispatch','review'].includes(w.phase))return '陈主管 · '+w.status;if(['assigned','executing','retest'].includes(w.phase))return (w.owner||'需主管明确执行人')+' · '+w.status;return '归档 · 保留完整记录'}
nextOwner=id=>jr(id).workId?workResponsible(state.work.find(w=>w.id===jr(id).workId)):'刘值班 · 接管并自动建单';
inQueue=id=>{const r=jr(id),w=state.work.find(w=>w.id===r.workId);return w?workInQueue(w):allowed('operator')&&r.stage==='discovered'};
function workInQueue(w){return allowed('analyst')&&['acknowledged','requested','rejected'].includes(w.phase)||allowed('supervisor')&&['analyzed','deferred','dispatch','review'].includes(w.phase)||allowed('engineer')&&w.ownerId===state.demoPerson&&['assigned','executing','retest'].includes(w.phase)||allowed('admin')&&w.flow?.quality!=='有效'&&!!w.flow}
ordinaryQueue=()=>{const rows=state.work.filter(w=>!w.journey&&(site==='all'||dev(w.device)?.site===site)&&workInQueue(w)).map(w=>({...w,type:'work',owner:workResponsible(w)}));if(allowed('operator'))for(const a of filteredAlarms().filter(a=>!caseForAlarm(a.id)&&a.status==='待确认'))rows.push({...a,type:'alarm',owner:'刘值班 · 接管并自动建单'});return rows};
queueTable=ids=>table(['工单 / 预警来源','状态','当前责任人','操作'],ids.map(id=>{const r=jr(id),c=cs(id);return `<tr><td><strong>${esc(c.title)}</strong><span class="id">${r.workId||'尚未接管'} · ${c.event}</span><span class="subtext">${c.kb} · ${c.subtitle}</span></td><td>${badge(r.workId?state.work.find(w=>w.id===r.workId).status:'待接管')}</td><td>${nextOwner(id)}</td><td>${wfAction(r.workId?'打开工单':'接管并建单',r.workId?`workDetail('${r.workId}')`:`openCase('${id}','actions')`)}</td></tr>`}));
const oldDecisionGap=decisionGap;
decisionGap=id=>jr(id).stage==='dispatch'?'方案已批准，待主管明确执行人与分派依据。':jr(id).stage==='cancelled'?'工单已取消，证据与操作记录保留；主管可以重开同一工单。':jr(id).stage==='acknowledged'?'工单已建立，分析人员可直接分析；值班人员可补充诊断交接。':oldDecisionGap(id);
const caseActionsV3=caseActions;
caseActions=id=>{const r=jr(id),w=state.work.find(w=>w.id===r.workId);let body=caseActionsV3(id);if(w)body=`<div class="work-anchor"><b>统一工单 ${w.id}</b><p>${w.status} · ${esc(w.source)} · ${esc(w.type)} · ${esc(w.priority)}优先级</p>${wfAction('打开此工单',`workDetail('${w.id}')`)}</div>`+body;
 if(r.stage==='dispatch'&&allowed('supervisor'))body+=`<label for="wf-assignee">执行人</label><select id="wf-assignee"><option value="engineer">王工</option><option value="engineer2">赵工</option></select><label for="wf-note">分派依据</label><textarea id="wf-note"></textarea>${wfAction('分派同一工单',`wfDispatch('${id}',$('#wf-assignee').value,$('#wf-note').value)`,true)}`;
 if(w&&allowed('supervisor'))body+=`<section class="support-block"><label for="work-reason">取消 / 重开依据（必填）</label><textarea id="work-reason"></textarea>${wfAction(['closed','cancelled'].includes(w.phase)?'重开同一工单':'取消工单',`transitionWork('${w.id}','${['closed','cancelled'].includes(w.phase)?'reopen':'cancel'}',${w.version})`)}</section>`;
 return body};
const caseDetailV3=caseDetail;
caseDetail=(id,tab)=>{const r=jr(id),w=state.work.find(w=>w.id===r.workId);if(tab==='history'&&w)return workHistory(w);return caseDetailV3(id,tab)};
function workHistory(w){return `<h3>${w.id} · 完整工单历史</h3><p>分析、审批、分派、检查、复测与验收均归属于此编号。迁移记录明确标识来源。</p><ul class="timeline">${w.history.map(h=>`<li><b>${esc(h.action||h.reason||'状态变更')}</b><small>${esc(h.actorName||PEOPLE[h.actor]?.name||h.actor)} · ${h.time}</small><p>${esc(h.from||'')} → ${esc(h.to||'')} · ${esc(h.reason||'')}</p><span class="id">${w.id}${h.id?' · '+esc(h.id):''}</span></li>`).join('')}</ul>${w.flow?.history.length?'<h3>原始事件轨迹（保留历史来源）</h3>'+wfHistory(w.flow):''}`}
function acknowledgeOrdinary(id,note){const a=state.alarms.find(a=>a.id===id);if(!a||!allowed('operator')||!String(note||'').trim())return false;if(a.work)return state.work.find(w=>w.id===a.work);if(a.status!=='待确认'&&a.status!=='已确认')return false;const w=makeWork({alarm:id,device:a.device,title:a.title,source:a.source==='预测模拟'?'预测预警':'告警接管',type:a.source==='预测模拟'?'预测性维护':'故障处理',priority:a.severity==='紧急'?'紧急':'中',description:note});a.work=w.id;a.status='处理中';a.acknowledgedBy=state.demoPerson;a.acknowledgedAt=time();w.evidence.push({id:`EVS-${id}`,workId:w.id,kind:'接管时测点快照',values:points(dev(a.device)),time:time()});workAudit(w,'接管告警并自动创建工单',note,'新建');render();return w}
ackAlarm=id=>{const key=caseForAlarm(id),note=$('#alarm-reason')?.value||$('#wf-note')?.value;if(key){const result=wfAck(key,note);if(result)toast('已接管，工单 '+jr(key).workId+' 已创建');return result}const w=acknowledgeOrdinary(id,note);if(w)toast('已接管，工单 '+w.id+' 已创建');return !!w};
createWork=id=>{const a=state.alarms.find(a=>a.id===id);if(a?.work){workDetail(a.work);return true}return ackAlarm(id)};
function woSetQuality(id,value){const w=state.work.find(w=>w.id===id);if(!w||!allowed('admin')||!['有效','缺失','迟到'].includes(value)||['closed','cancelled'].includes(w.phase))return false;if(w.journey)return wfQuality(w.journey,value);const from=w.status;dev(w.device).quality=value;for(const x of state.work.filter(x=>x.device===w.device&&!x.journey&&!['closed','cancelled'].includes(x.phase))){for(const d of x.diagnoses)d.superseded=true;if(['analyzed','deferred','dispatch'].includes(x.phase))x.phase='requested';workAudit(x,'更新证据质量',value,from)}render();return true}
function woCreate(data){if(!allowed('operator','analyst','supervisor','engineer'))return denied();if(!data||!String(data.title||'').trim()||!String(data.description||'').trim()||!dev(data.device)||data.site!==dev(data.device).site||!WO_TYPES.includes(data.type)||!WO_PRIORITIES.includes(data.priority))return false;const w=makeWork({title:data.title.trim(),description:data.description.trim(),device:data.device,site:data.site,type:data.type,priority:data.priority,source:data.type==='预测性维护'?'主动预防':'人工创建',alarm:null});w.evidence.push({id:`EVS-${w.id}-INITIAL`,workId:w.id,kind:'建单时测点快照',time:time(),values:points(dev(w.device))});workAudit(w,'人工创建工单',w.description,'新建');render();return w.id}
function newWorkForm(){if(!allowed('operator','analyst','supervisor','engineer'))return denied();modal('新建工单',`<p>故障、预测性维护、预防巡检与容量变更均从同一工单流程开始。</p><label for="wo-title">标题</label><input id="wo-title" maxlength="120"><div class="form-grid"><div><label for="wo-site">站点</label><select id="wo-site" onchange="newWorkAssets()">${SITES.map(s=>`<option>${s}</option>`).join('')}</select></div><div><label for="wo-device">资产</label><select id="wo-device"></select></div><div><label for="wo-type">工单类型</label><select id="wo-type">${WO_TYPES.map(s=>`<option>${s}</option>`).join('')}</select></div><div><label for="wo-priority">优先级</label><select id="wo-priority">${WO_PRIORITIES.map(s=>`<option ${s==='中'?'selected':''}>${s}</option>`).join('')}</select></div></div><label for="wo-description">现象、预防目的与证据说明</label><textarea id="wo-description"></textarea>${wfAction('创建工单',"submitNewWork()",true)}`);newWorkAssets()}
function newWorkAssets(){$('#wo-device').innerHTML=state.devices.filter(d=>d.site===$('#wo-site').value).map(d=>`<option value="${d.id}">${d.id} · ${d.name}</option>`).join('')}
function submitNewWork(){const id=woCreate({title:$('#wo-title').value,site:$('#wo-site').value,device:$('#wo-device').value,type:$('#wo-type').value,priority:$('#wo-priority').value,description:$('#wo-description').value});if(!id)return toast('请填写标题和说明，并选择同站点资产、类型与优先级');$('#dialog').close();navigate('work');workDetail(id);toast('已创建 '+id)}
function woTransition(id,action,version,options={}){const w=state.work.find(w=>w.id===id);if(!w||w.version!==version)return false;const note=String(options.note||'').trim(),supervisor=allowed('supervisor'),mine=allowed('engineer')&&w.ownerId===state.demoPerson,old=w.status;if(!note)return false;
 if(action==='cancel'){if(!supervisor||['closed','cancelled'].includes(w.phase))return false;w.phase='cancelled'}
 else if(action==='reopen'){if(!supervisor||!['closed','cancelled'].includes(w.phase))return false;w.caseArchive=w.caseArchive||[];if(w.caseId||w.flow?.caseId)w.caseArchive.push({caseId:w.caseId||w.flow.caseId,workId:w.id,acceptance:w.acceptance||{reviewer:w.flow?.reviewer,note:w.flow?.reviewNote},archivedAt:time()});w.caseId=null;w.acceptance=null;w.phase='requested';w.ownerId=null;w.owner='';w.testPassed=false;if(w.flow){w.flow.checks=[];w.flow.caseId=null;w.flow.reviewNote=null;for(const d of w.flow.diagnoses)d.superseded=true}}
 else if(w.journey)return false;
 else if(action==='reject'){if(!supervisor||!['analyzed','deferred','review'].includes(w.phase))return false;w.phase=w.phase==='review'?'executing':'rejected';w.testPassed=false}
 else if(action==='next'){
  if(['acknowledged','requested','rejected'].includes(w.phase)&&allowed('analyst','engineer')){if(dev(w.device).quality!=='有效')return false;const k=KNOWLEDGE[dev(w.device).type==='精密空调'?'空调':'UPS'];w.diagnoses.push({id:`DX-${w.id}-${w.diagnoses.length+1}`,workId:id,actor:state.demoPerson,time:time(),conclusion:note,plan:options.plan||note,knowledgeId:k.id,knowledgeVersion:'本地演示知识快照 v4',knowledgeText:k.text,evidence:w.evidence.at(-1)?.id});w.phase='analyzed'}
  else if(['analyzed','deferred'].includes(w.phase)&&supervisor){if(dev(w.device).quality!=='有效'||!w.diagnoses.length||w.diagnoses.at(-1).superseded)return false;w.decisions.push({id:`DEC-${w.id}-${w.decisions.length+1}`,workId:id,actor:state.demoPerson,time:time(),choice:'approve',note,diagnosis:w.diagnoses.at(-1).id});w.phase='dispatch'}
  else if(w.phase==='dispatch'&&supervisor&&PEOPLE[options.assignee]?.kind==='engineer'){if(dev(w.device).quality!=='有效')return false;w.ownerId=options.assignee;w.owner=PEOPLE[options.assignee].name;w.phase='assigned'}
  else if(w.phase==='assigned'&&mine)w.phase='executing';
  else if(w.phase==='executing'&&mine){w.checkRecords=w.checkRecords||[];w.checkRecords.push({id:`CHECK-${id}-${w.checkRecords.length+1}`,workId:id,actor:state.demoPerson,note,time:time()});w.phase='retest'}
  else if(w.phase==='retest'&&mine&&['通过','不通过'].includes(options.test)){if(dev(w.device).quality!=='有效')return false;w.testPassed=options.test==='通过';w.testActor=state.demoPerson;w.tests.push({id:`TEST-${w.id}-${w.tests.length+1}`,workId:id,passed:w.testPassed,actor:state.demoPerson,time:time(),note,evidence:`POST-${id}-${w.tests.length+1}`});w.phase=w.testPassed?'review':'executing';const a=state.alarms.find(a=>a.id===w.alarm);if(a)a.signalState=w.testPassed?'recovered':'active'}
  else if(w.phase==='review'&&supervisor&&dev(w.device).quality==='有效'&&w.testPassed&&w.testActor!==state.demoPerson&&w.ownerId!==state.demoPerson){w.phase='closed';w.caseId=`CASE-${id}`;w.acceptance={workId:id,actor:state.demoPerson,time:time(),note}}
  else return false;
 }else return false;
 const a=state.alarms.find(a=>a.id===w.alarm);if(a)a.status=w.phase==='closed'?'已关闭':w.phase==='cancelled'?'已确认':'处理中';workAudit(w,action==='next'?'工单交接':action==='reopen'?'重开同一工单':action==='cancel'?'取消工单':'退回补充',options.test?note+'；复测：'+options.test:note,old);if(w.flow){w.flow.history.push({id:`TRACE-${id}-${w.flow.history.length+1}`,workId:id,time:time(),actor:state.demoPerson,action:person().name+' · '+action,detail:note})}save();render();return true}
transitionWork=(id,action,version)=>{const ok=woTransition(id,action,version,{note:$('#work-reason')?.value,assignee:$('#work-owner')?.value,test:$('#work-test')?.value,plan:$('#work-plan')?.value});if(!ok)toast('请检查当前身份、状态、版本与必填依据');return ok};
const genericDetailV3=genericDetail;
genericDetail=(d,tab)=>{const w=detail.type==='work'?state.work.find(w=>w.id===detail.id):null;if(!w)return genericDetailV3(d,tab);
 const mine=allowed('engineer')&&w.ownerId===state.demoPerson,supervisor=allowed('supervisor');
 if(tab==='overview')return `<h3>${esc(w.title)}</h3><dl><dt>统一工单</dt><dd>${w.id}</dd><dt>状态 / 当前责任</dt><dd>${w.status} · ${workResponsible(w)}</dd><dt>来源 / 类型 / 优先级</dt><dd>${esc(w.source)} / ${esc(w.type)} / ${esc(w.priority)}</dd><dt>站点 / 设备</dt><dd>${esc(w.site)} · ${w.device}</dd><dt>描述</dt><dd>${esc(w.description)}</dd><dt>关联告警</dt><dd>${w.alarm||'主动建单，无故障告警'}</dd><dt>案例</dt><dd>${w.caseId||'验收后生成'}</dd></dl><div class="toolbar">${wfAction('关联资产',`assetDetail('${w.device}')`)}${w.alarm?wfAction('关联告警',`alarmDetail('${w.alarm}')`):''}</div>`;
 if(tab==='history')return workHistory(w);
 if(tab==='evidence')return `<h3>工单证据 ${w.id}</h3><p>当前证据质量：${esc(d.quality)}；非有效质量不得提交诊断、批准或复测。</p>${allowed('admin')?`<label for="wo-quality">演示证据质量</label><select id="wo-quality" onchange="woSetQuality('${w.id}',this.value)">${['有效','缺失','迟到'].map(q=>`<option ${d.quality===q?'selected':''}>${q}</option>`).join('')}</select>`:''}${w.evidence.map(e=>`<div class="split-note"><b>${esc(e.id)} · ${esc(e.kind)}</b><p>${w.id} · ${e.time||'历史快照'}</p>${Array.isArray(e.values)&&e.values[0]?.name?table(['测点','值','单位','质量'],e.values.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.value)}</td><td>${esc(p.unit)}</td><td>${esc(p.quality)}</td></tr>`)):''}</div>`).join('')}<h3>检查与复测记录</h3>${(w.checkRecords||[]).map(c=>`<p>${c.id} · ${w.id} · ${esc(c.note)}</p>`).join('')}${w.tests.map(t=>`<div class="split-note">${t.id} · ${w.id} · ${t.passed?'通过，仍需独立验收':'失败，返回处理'}<p>${esc(t.note)}</p></div>`).join('')||'<p>暂无复测，不能声称恢复。</p>'}`;
 if(tab==='analysis')return `<h3>工单分析与知识依据</h3><p>固定规则参考与人工分析记录；不运行真实 AI。缺少设备适用依据时须补充现场资料，不直接采用其他型号的规程。</p>${genericDetailV3(d,tab)}<h3>已提交分析</h3>${w.diagnoses.map(x=>`<div class="split-note"><b>${x.id} · ${w.id}</b><p>${esc(x.conclusion)}</p><p>${esc(x.knowledgeId)} · ${esc(x.knowledgeVersion)}</p><p>${esc(x.knowledgeText)}</p><p>证据 ${esc(x.evidence||'旧版未记录')}</p></div>`).join('')||'<p>待分析人员补充证据与建议方案。</p>'}${wfAction('前往分析 / 交接',"detailTab('actions')")}`;
 const canAnalyze=allowed('analyst','engineer')&&['acknowledged','requested','rejected'].includes(w.phase),canNext=canAnalyze||supervisor&&['analyzed','deferred','dispatch','review'].includes(w.phase)||mine&&['assigned','executing','retest'].includes(w.phase);
 const labels={acknowledged:'提交分析与方案',requested:'提交分析与方案',rejected:'重新提交分析',analyzed:'批准方案，转待派单',deferred:'批准方案，转待派单',dispatch:'分派工单',assigned:'接受工单',executing:'提交检查，进入复测',retest:'提交复测结果',review:'独立验收并关闭'};
 return `<h3>${w.id} · ${badge(w.status)}</h3><p>当前责任：${workResponsible(w)} · 操作人：${person().name}</p><div class="split-note">${esc(w.description)}<p>信号恢复与业务关闭分开记录；复测通过后仍需主管独立验收。</p></div>${canNext||supervisor?`<label for="work-reason">分析 / 操作依据（必填）</label><textarea id="work-reason"></textarea>${canAnalyze?'<label for="work-plan">建议方案（可在依据中一并填写）</label><textarea id="work-plan"></textarea>':''}${w.phase==='dispatch'?'<label for="work-owner">执行人</label><select id="work-owner"><option value="engineer">王工</option><option value="engineer2">赵工</option></select>':''}${w.phase==='retest'?'<label for="work-test">复测结论</label><select id="work-test"><option value="">请选择</option><option>通过</option><option>不通过</option></select>':''}<div class="toolbar">${canNext?wfAction(labels[w.phase],`transitionWork('${w.id}','next',${w.version})`,true):''}${supervisor&&['analyzed','deferred','review'].includes(w.phase)?wfAction('退回补充 / 返工',`transitionWork('${w.id}','reject',${w.version})`):''}${supervisor?wfAction(['closed','cancelled'].includes(w.phase)?'重开同一工单':'取消工单',`transitionWork('${w.id}','${['closed','cancelled'].includes(w.phase)?'reopen':'cancel'}',${w.version})`):''}</div>`:'<p>当前岗位只读，请由当前责任人推进。</p>'}<h3>方案审批</h3>${w.decisions.map(x=>`<p>${x.id} · ${w.id} · ${esc(x.note)}</p>`).join('')||'<p>尚无审批记录。</p>'}`;
};
WORK_STATES.splice(0,WORK_STATES.length,'待分析','待方案审批','待派单','待接单','处理中','待复测','待验收','已关闭');
views.work=()=>{const rows=state.work.filter(w=>(site==='all'||dev(w.device)?.site===site)&&`${w.id}${w.device}${w.title}${w.source}`.toLowerCase().includes(query.toLowerCase())&&(filter==='全部'||w.status===filter));const p=paginate(rows);return `<section class="card work-center">${head('工单中心 · 全流程协同',allowed('operator','analyst','supervisor','engineer')?wfAction('新建工单','newWorkForm()',true):'')}<p>接管即建单，主动维护也从这里开始。每次分析、审批、分派和复测都使用同一工单编号。</p><div class="work-status-strip">${WORK_STATES.map(s=>`<button class="${filter===s?'active':''}" onclick="filter='${s}';pageNo=1;render()"><b>${state.work.filter(w=>w.status===s&&(site==='all'||dev(w.device)?.site===site)).length}</b><span>${s}</span></button>`).join('')}</div>${toolbar('搜索工单、资产、标题或来源',['全部',...WORK_STATES,'已取消'])}${table(['工单 / 来源','站点 / 资产','类型 / 优先级','状态 / 当前责任','操作'],p.rows.map(w=>`<tr><td class="wrap-cell"><strong>${esc(w.title)}</strong><span class="id">${w.id}</span><span class="subtext">${esc(w.source)}${w.eventId?' · '+w.eventId:''}</span></td><td>${esc(w.site)}<span class="id">${w.device}</span></td><td>${esc(w.type)}<span class="id">${esc(w.priority)}优先级</span></td><td>${badge(w.status)}<span class="id">${workResponsible(w)}</span></td><td>${wfAction('打开工单',`workDetail('${w.id}')`)}</td></tr>`))}${p.footer}${!rows.length?'<div class="empty">当前筛选下暂无工单。点击“新建工单”发起主动维护，或接管告警自动创建工单。</div>':''}</section>`};
nativeViews.work=views.work;
modules.find(m=>m[0]==='work')[1]='工单中心';
subtitles.work='工单是协同底座：接管即建单，分析、决策、执行与复测全程追溯。';
const oldDrawWork=drawDetail;
drawDetail=()=>{oldDrawWork();if(!detailDialog.open||!detail)return;const w=detail.type==='work'?state.work.find(w=>w.id===detail.id):detail.caseId?state.work.find(w=>w.id===jr(detail.caseId).workId):detail.type==='alarm'?state.work.find(w=>w.alarm===detail.id):null;if(w){const identity=detailDialog.querySelector('.drawer-identity');if(detail.type==='work')identity.querySelector('h2').textContent=w.title;identity.insertAdjacentHTML('beforeend',`<div class="work-anchor"><b>${w.id}</b> ${badge(w.status)}<span class="id">${workResponsible(w)}</span>${detail.type!=='work'?wfAction('打开关联工单',`workDetail('${w.id}')`):''}</div>`)}};
window.WO={get:id=>state.work.find(w=>w.id===id),list:()=>state.work,create:woCreate,transition:woTransition,acknowledgeAlarm:acknowledgeOrdinary,setQuality:woSetQuality,types:WO_TYPES,priorities:WO_PRIORITIES,sites:SITES,open:workDetail,newForm:newWorkForm};

window.WF={getState:()=>ensureJourneys(),cases:CASES,knowledge:WF_KNOWLEDGE,people:PEOPLE,person:()=>state.demoPerson,switchPerson,select:wfSelect,go:wfGo,acknowledge:wfAck,requestDiagnosis:wfRequest,analyze:wfAnalyze,decide:wfDecide,dispatch:wfDispatch,startWork:wfStart,check:wfCheck,submitChecks:wfSubmit,retest:wfRetest,closeCase:wfClose,returnWork:wfReturn,setQuality:wfQuality,reset:wfReset,open:openCase,close:closeDetail};
